use std :: path :: { Path , PathBuf } ; use forge_domain :: { ContextSummary , SummaryMessage , SummaryTool , Transformer } ; use forge_domain :: { Role , SummaryBlock , SummaryMessage as Block , SummaryToolCall } ; use pretty_assertions :: assert_eq ; use super :: * ; # [doc = " Strips the working directory prefix from all file paths in tool calls."] # [doc = ""] # [doc = " This transformer removes the working directory prefix from file paths in"] # [doc = " FileRead, FileUpdate, and FileRemove tool calls, making paths relative to"] # [doc = " the working directory. This is useful for reducing context size and making"] # [doc = " summaries more portable across different environments."] # [doc = ""] # [doc = " # Platform-Specific Behavior"] # [doc = ""] # [doc = " This implementation uses `std::path::Path::strip_prefix()`, which is"] # [doc = " **platform-specific**:"] # [doc = ""] # [doc = " - On **Windows**: Recognizes and strips Windows paths (e.g., `C:\\Users\\...`,"] # [doc = "   `\\\\server\\share\\...`)"] # [doc = " - On **Unix/macOS**: Only recognizes Unix paths (forward slashes). Windows"] # [doc = "   paths are treated as literal strings and left unchanged."] # [doc = ""] # [doc = " This means:"] # [doc = " - Windows paths in summaries will only be stripped when running on Windows"] # [doc = " - Unix paths in summaries will only be stripped when running on Unix/macOS"] # [doc = " - Cross-platform path handling would require a custom implementation that"] # [doc = "   doesn't rely on the OS-specific `std::path::Path`"] # [doc = ""] # [doc = " For truly cross-platform path stripping (e.g., stripping Windows paths on"] # [doc = " Unix or vice versa), consider implementing custom path parsing logic that"] # [doc = " handles both path styles regardless of the host OS."] pub struct StripWorkingDir { working_dir : PathBuf , }